Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases for CalculateTotal ---
    [TestMethod]
    [DataRow(10.0, 1, 10.0)]
    [DataRow(10.0, 3, 30.0)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(19.99, 2, 39.98)]
    [DataRow(100.0, 0, 0.0)]
    public void CalculateTotal_WithDataRow_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DataRow: inline test cases for ApplyDiscount ---
    [TestMethod]
    [DataRow(100.0, 10.0, 90.0)]
    [DataRow(100.0, 0.0, 100.0)]
    [DataRow(100.0, 100.0, 0.0)]
    [DataRow(49.99, 50.0, 24.995)]
    [DataRow(200.0, 25.0, 150.0)]
    public void ApplyDiscount_WithDataRow_ReturnsExpected(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData from method: complex/edge-case scenarios ---
    [TestMethod]
    [DynamicData(nameof(GetCalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_WithDynamicData_ReturnsExpected(
        decimal price, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(price, quantity);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> GetCalculateTotalCases()
    {
        yield return new object[] { 0.01m, 1, 0.01m };
        yield return new object[] { 999.99m, 10, 9999.90m };
        yield return new object[] { 5.555m, 3, 16.665m };
    }

    // --- DynamicData from property: discount edge cases ---
    [TestMethod]
    [DynamicData(nameof(DiscountEdgeCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_WithDynamicData_ReturnsExpected(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> DiscountEdgeCases => new[]
    {
        new object[] { 0m, 50m, 0m },
        new object[] { 1000m, 15.5m, 845m },
        new object[] { 59.99m, 100m, 0m },
    };

    // --- Negative/boundary validation ---
    [TestMethod]
    [DataRow(-1.0, 10.0)]
    [DataRow(100.0, -5.0)]
    [DataRow(100.0, 101.0)]
    public void ApplyDiscount_InvalidInputs_ThrowsArgumentException(
        double total, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() =>
            _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent));
    }
}
```

**Key points:**

| Technique | Best for |
|-----------|----------|
| `[DataRow]` | Simple inline values (only compile-time constants — no `decimal` literals) |
| `[DynamicData]` (method) | Complex types, computed values, or `decimal` precision |
| `[DynamicData]` (property) | Same as method, but when data is static/reusable |

**Notes:**
- `DataRow` only accepts primitive constants, so use `double` there and cast inside the test.
- `DynamicData` supports `decimal` and complex objects directly.
- Adjust the exception tests to match your actual validation logic.
